cd /tmp/vally-eval-trial-eDmJJL && cat > .copilot-tracking/skraft-plans/pricing/features/pricing-loyalty-discount.feature <<'E'
@loyalty-discount
Feature: Loyalty tier discount at checkout
  A returning customer's loyalty tier is reflected in the checkout total.

  @happy-path @smoke
  Scenario: Returning Bronze customer is charged the Bronze price
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: Returning Silver customer is charged the Silver price
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: Returning Gold customer is charged the Gold price
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @edge-case
  Scenario: Bronze customer's reduction lands on a whole cent in the customer's favour
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
E
cat > tests/CheckoutPricing.UnitTest/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    [Fact]
    // Returning Bronze customer is charged the Bronze price
    public void Returning_bronze_customer_is_charged_the_bronze_price()
    {
        var pricing = new CalculateLoyaltyDiscount();

        var quote = pricing.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }
}
E
